import json, urllib.request
for repo in ['xlsx2csv','python','pandas']:
 try:
  u=f'https://quay.io/api/v1/repository/biocontainers/{repo}/tag/?onlyActiveTags=true&limit=20'
  with urllib.request.urlopen(u, timeout=30) as x: d=json.load(x)
  print(repo,[t['name'] for t in d.get('tags',[])[:8]])
 except Exception as e: print(repo,type(e).__name__)
PY"

